import{_ as a,a0 as p,w as u,s as o,ao as l,I as i,x as n,a1 as r,A as e}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const b=JSON.parse('{"title":"Linux 黑话解释：什么是 Linux 中的 GUI、CLI 和 TUI？ | LCTT x X-CMD","titleTemplate":false,"description":"Linux 黑话解释：什么是 Linux 中的 GUI、CLI 和 TUI？ | LCTT (202011) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 黑话解释：什么是 Linux 中的 GUI、CLI 和 TUI？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 黑话解释：什么是 Linux 中的 GUI、CLI 和 TUI？ | LCTT (202011) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202011/20201103 Linux Jargon Buster- What are GUI, CLI and TUI in Linux","title":"Linux 黑话解释：什么是 Linux 中的 GUI、CLI 和 TUI？","tag":"202011","desc":""},"relativePath":"202011/20201103 Linux Jargon Buster- What are GUI, CLI and TUI in Linux.md","filePath":"[post].md"}'),I={name:"202011/20201103 Linux Jargon Buster- What are GUI, CLI and TUI in Linux.md"};function m(f,t,d,L,x,T){const s=p("Link");return u(),o("div",null,[t[34]||(t[34]=l('<h1 id="linux-黑话解释-什么是-linux-中的-gui、cli-和-tui" tabindex="-1">Linux 黑话解释：什么是 Linux 中的 GUI、CLI 和 TUI？ <a class="header-anchor" href="#linux-黑话解释-什么是-linux-中的-gui、cli-和-tui" aria-label="Permalink to “Linux 黑话解释：什么是 Linux 中的 GUI、CLI 和 TUI？”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202011/10/092051zw3ofb365a63fahl.jpg" alt=""></p><p>当你开始使用 Linux 并关注关于 Linux 的网站和论坛时，你会经常遇到诸如 GUI、CLI 等术语，有时还会遇到 TUI。</p><p>这一章的 Linux 黑话解释简要解释了这些术语，以便你作为一个（新的）Linux 用户在使用这些缩写词时能够更好地理解上下文。</p><p>说实话，像 GUI、CLI 或 TUI 这样的术语并不是 Linux 的专属术语。这些都是通用的计算术语，你会发现在非 Linux 的讨论中也会用到它们。</p><h3 id="gui-图形用户界面graphical-user-interface" tabindex="-1">GUI - <ruby>图形用户界面<rt>Graphical User Interface</rt></ruby> <a class="header-anchor" href="#gui-图形用户界面graphical-user-interface" aria-label="Permalink to “GUI - 图形用户界面Graphical User Interface”">​</a></h3><p>这可能是你在这里最常遇到的词汇。这是因为我们专注于桌面 Linux 用户，并试图涵盖易于使用的图形化方法和应用程序。</p><p>GUI 应用程序（或图形应用程序）基本上是指任何可以与你的鼠标、触摸板或触摸屏交互的东西。有了图标和其他视觉概念，你可以使用鼠标指针来访问功能。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2018/04/gimp-2-10-interface.jpg?resize=800%2C450&amp;ssl=1" alt="GIMP：一个用于照片编辑的GUI应用程序"></p>',9)),i("p",null,[t[1]||(t[1]=n("在 Linux 上，",-1)),r(s,{href:"https://itsfoss.com/what-is-desktop-environment/"},{default:e(()=>[...t[0]||(t[0]=[n("桌面环境",-1)])]),_:1}),t[2]||(t[2]=n("为你提供了与系统交互的图形界面，然后，你可以使用 GUI 应用程序，如 GIMP，VLC、Firefox、LibreOffice、文件管理器等来完成各种任务。",-1))]),t[35]||(t[35]=l('<p>GUI 使普通用户的计算机使用变得更加容易，否则它将仍然是一个极客专用区。</p><h3 id="cli-命令行界面command-line-interface" tabindex="-1">CLI - <ruby>命令行界面<rt>Command Line Interface</rt></ruby> <a class="header-anchor" href="#cli-命令行界面command-line-interface" aria-label="Permalink to “CLI - 命令行界面Command Line Interface”">​</a></h3><p>CLI 基本上是一个接受输入来执行某种功能的命令行程序。基本上，任何可以在终端中通过命令使用的应用程序都属于这一类。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2020/10/apt-cache-search-names-only.png?resize=759%2C209&amp;ssl=1" alt="apt-cache 是一个 CLI 工具，用于在基于 Debian 的系统上与 APT 缓存交互"></p><p>早期的电脑与操作系统交互没有鼠标，你必须使用命令与机器互动。</p><p>如果你认为这都算困难，那你应该知道，早期的计算机甚至没有一个屏幕可以看到正在输入的东西，他们用实体的纸质打印机看到他们的输入命令。我从来没有用过这样的电脑，也没有在现实生活中看到过。我用过的最接近的东西是学习期间的单片机套件。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2020/11/Ken_Thompson_and_Dennis_Ritchie_at_PDP-11.jpg?resize=800%2C641&amp;ssl=1" alt="肯•汤普森和丹尼斯•里奇在 PDP11 电脑上开发 UNIX 操作系统"></p>',7)),i("p",null,[t[4]||(t[4]=n("现在的 CLI 还有用吗？当然有。命令总是有它的好处，特别是当你处理操作系统的核心功能和配置时，比如设置防火墙、管理网络甚至",-1)),r(s,{href:"https://itsfoss.com/package-manager/"},{default:e(()=>[...t[3]||(t[3]=[n("包管理",-1)])]),_:1}),t[5]||(t[5]=n("。",-1))]),t[36]||(t[36]=i("p",null,"你可能会有一个基于 GUI 的应用程序来完成同样的任务，但命令可以让你更精细地访问这些功能。在一些情况下，你会发现 GUI 应用程序也会用命令（在它们的代码中使用）与操作系统交互。",-1)),t[37]||(t[37]=i("p",null,[i("img",{src:"https://i2.wp.com/itsfoss.com/wp-content/uploads/2019/11/handbrake.png?resize=800%2C537&ssl=1",alt:"Handbrake GUI 应用程序在底层使用 FFMPEG CLI 工具"})],-1)),i("p",null,[t[8]||(t[8]=n("许多流行的 GUI 应用程序往往是基于 CLI 工具的。以",-1)),r(s,{href:"https://itsfoss.com/handbrake/"},{default:e(()=>[...t[6]||(t[6]=[n("Handbrake",-1)])]),_:1}),t[9]||(t[9]=n(" 为例。这是一个流行的开源媒体转换器，它底层使用的是 ",-1)),r(s,{href:"https://itsfoss.com/ffmpeg/"},{default:e(()=>[...t[7]||(t[7]=[n("FFMPEG 命令行",-1)])]),_:1}),t[10]||(t[10]=n("工具。",-1))]),t[38]||(t[38]=l('<p>很明显，使用命令行工具没有图形工具那么简单。不要担心。除非你有特殊需要，否则你应该可以用图形化的方式使用 Linux 系统。然而，了解基本的 Linux 命令会有很大的帮助。</p><h3 id="tui-终端用户界面terminal-user-interface-也称为基于文本的用户界面text-based-user-interface" tabindex="-1">TUI - <ruby>终端用户界面<rt>Terminal User Interface</rt></ruby>（也称为<ruby>基于文本的用户界面<rt>Text-based User Interface</rt></ruby>） <a class="header-anchor" href="#tui-终端用户界面terminal-user-interface-也称为基于文本的用户界面text-based-user-interface" aria-label="Permalink to “TUI - 终端用户界面Terminal User Interface（也称为基于文本的用户界面Text-based User Interface）”">​</a></h3><p>这是三者中最不常见的名词。TUI 基本上部分是 GUI，部分是 CLI。糊涂了吗？让我为你解释一下。</p><p>你已经知道，早期的计算机使用 CLI。在实际的 GUI 出现之前，基于文本的用户界面在终端中提供了一种非常基本的图形交互。你会有更多的视觉效果，也可以使用鼠标和键盘与应用程序进行交互。</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2020/10/nnn-file-browser.jpg?resize=800%2C597&amp;ssl=1" alt="终端中的 nnn 文件浏览器"></p><p>TUI 是基于文本的用户界面或终端用户界面的缩写。“基于文本”这个说法主要是因为你在屏幕上有一堆文本，而“终端用户界面”的说法是因为它们只在终端中使用。</p>',6)),i("p",null,[t[13]||(t[13]=n("TUI 的应用虽然不是那么常见，但你还是有一些的。",-1)),r(s,{href:"https://itsfoss.com/terminal-web-browsers/"},{default:e(()=>[...t[11]||(t[11]=[n("基于终端的 Web 浏览器",-1)])]),_:1}),t[14]||(t[14]=n("是 TUI 程序的好例子。",-1)),r(s,{href:"https://itsfoss.com/best-command-line-games-linux/"},{default:e(()=>[...t[12]||(t[12]=[n("基于终端的游戏",-1)])]),_:1}),t[15]||(t[15]=n("也属于这一类。",-1))]),t[39]||(t[39]=i("p",null,[i("img",{src:"https://i2.wp.com/itsfoss.com/wp-content/uploads/2017/07/cmus-interface.png?resize=734%2C436&ssl=1",alt:"CMUS 是基于终端的音乐播放器"})],-1)),i("p",null,[t[17]||(t[17]=n("当你在 ",-1)),r(s,{href:"https://itsfoss.com/install-media-codecs-ubuntu/"},{default:e(()=>[...t[16]||(t[16]=[n("Ubuntu 中安装多媒体编解码器",-1)])]),_:1}),t[18]||(t[18]=n("时，你可能会遇到 TUI，你必须接受 EULA 或做出选择。",-1))]),t[40]||(t[40]=i("p",null,"TUI 应用程序不像 GUI 应用程序那样用户友好，它们经常会有学习曲线，但它们比命令行工具更容易使用一些。",-1)),t[41]||(t[41]=i("h3",{id:"最后",tabindex:"-1"},[n("最后…… "),i("a",{class:"header-anchor",href:"#最后","aria-label":"Permalink to “最后……”"},"​")],-1)),t[42]||(t[42]=i("p",null,"TUI 应用程序通常也被认为是 CLI 应用程序，因为它们被限制在终端上。在我看来，你是否认为它们与 CLI 不同，这取决于你。",-1)),t[43]||(t[43]=i("p",null,"我希望你喜欢这篇 Linux 黑话解释。如果你对这个系列的主题有什么建议，请在评论中告诉我，我将在以后尽量涵盖它们。",-1)),t[44]||(t[44]=i("hr",null,null,-1)),i("p",null,[t[20]||(t[20]=n("via: ",-1)),r(s,{href:"https://itsfoss.com/gui-cli-tui/"},{default:e(()=>[...t[19]||(t[19]=[n("https://itsfoss.com/gui-cli-tui/",-1)])]),_:1})]),i("p",null,[t[25]||(t[25]=n("作者：",-1)),r(s,{href:"https://itsfoss.com/author/abhishek/"},{default:e(()=>[...t[21]||(t[21]=[n("Abhishek Prakash",-1)])]),_:1}),t[26]||(t[26]=n(" 选题：",-1)),r(s,{href:"https://github.com/lujun9972"},{default:e(()=>[...t[22]||(t[22]=[n("lujun9972",-1)])]),_:1}),t[27]||(t[27]=n(" 译者：",-1)),r(s,{href:"https://github.com/wxy"},{default:e(()=>[...t[23]||(t[23]=[n("wxy",-1)])]),_:1}),t[28]||(t[28]=n(" 校对：",-1)),r(s,{href:"https://github.com/wxy"},{default:e(()=>[...t[24]||(t[24]=[n("wxy",-1)])]),_:1})]),i("p",null,[t[31]||(t[31]=n("本文由 ",-1)),r(s,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...t[29]||(t[29]=[n("LCTT",-1)])]),_:1}),t[32]||(t[32]=n(" 原创编译，",-1)),r(s,{href:"https://linux.cn/"},{default:e(()=>[...t[30]||(t[30]=[n("Linux中国",-1)])]),_:1}),t[33]||(t[33]=n(" 荣誉推出",-1))])])}const g=a(I,[["render",m]]);export{b as __pageData,g as default};
